// Proactive English C1 · Syria Edition · Book 2 · Unit 15 — Answer Key
const L = require('./lib');
const { p, h1, h2, pb, sp, box, table, C } = L;
const out = [];
const S = (t) => p(t, { bold: true, color: C.teal, before: 160, after: 60 });
const A = (t) => p(t, { indent: 200, after: 50 });
const SAMPLE = (paras) => box('Sample answer', paras, 'FFFFFF', C.navy);
const NOTE = (t) => box('Note', [t], C.lyellow, C.orange);

out.push(h1('Unit 15  The Letter Whose Date Has Come — Answer Key'));
out.push(p('_Proactive English · C1 · Book 2 · Syria Edition · Answer Key_', { color: '7F7F7F' }));
out.push(box('How to use this key — and read the second paragraph before you plan the unit', [
  'Every task has an answer or a **full sample**. **No model in this book contains a sentence about its own writing**, and the two declared exceptions in the level are 1.6 and 24.1.',
  '⚠ **This unit depends on a document the course did not write and cannot produce: the sealed letters of B2 24.6.** **Twelve students sealed one at the end of the B2 course, each set the date themselves, and each gave it to somebody who was not a friend.** **Two of those twelve are in this room.** **One envelope is due and one is not.** ⚠ **Do not plan this unit as though everybody has one.** **Eight of your ten students have no envelope at all** — **and the unit is written for that room and not for an ideal one, which is why 15.3 exists.**',
  '**What the eight have instead, and it is nearly as good.** **Their _cannot yet_ list from 1.2, now about sixteen months old, and the first document any of them wrote in September of last year.** ⚠ **The list has one property the letters do not: every item on it is a dated claim about what its writer could not do**, and all of them can now be checked. **A student who arrives saying they have nothing has twelve months of this course behind them and 1.6 is at least that old.**',
  '**Peer review stays at band 3 and this is the third unit of it.** **Unsigned slip; the writer answers in one line that concedes or refuses with a reason.**',
  '**15.7 carries the examination papers.** **Reading and Use of English Part 7** is the gapped text, five gaps and six paragraphs, met once before in 6.7; **Writing Part 1** is the essay; **Listening Part 3** is a long interview with four options a question.',
  '⚠ **And the sentence to say in the first minute and then not again: nothing in these seven cycles is about being embarrassed by your own prose.** **Embarrassment is the ordinary first reaction and it produces a verdict on the writer and no information about the writing.** **The first reaction in this class was laughter and it is the thing to get past in four minutes** — **and the way past it is mechanical: read the old sentence aloud, exactly, with no tone at all.**',
], C.lblue, C.navy));

// ===================== 15.1 =====================
out.push(pb());
out.push(h2('15.1  Your own prose, two years on'));
out.push(S('Stage 1 · Get ready'));
out.push(A('**a** Open. ⚠ **Three facts per student and no comment on the writing**, which the room will break at once because an old document invites a verdict. **Write the ten dates oldest first and leave them up**: the order matters in 15.4, where a chronological reading is the whole exercise. **In this class the oldest document is three years old and the newest is sixteen months** — **and the student with the oldest has the hardest cycle, not the easiest, because a three-year-old text cannot be read sentence by sentence in forty-five minutes.**'));
out.push(A('**b** Evidence: **2** and **4**. ⚠ **Both quote an old claim and then give a dated finding.** **1, 3 and 5 are verdicts on the writer** — _I cannot believe I wrote that_, _it is embarrassing_, _I was much less confident_ — **and the room should be made to say what each one tells a reader about the writing, which is nothing.** **5 is the one to spend time on**: it sounds like an observation and it is a comparison with no evidence on either side of it.'));
out.push(S('Stage 2 · Listen and read'));
out.push(A('**a** **B** — ⚠ **evidence**: a dated claim by a named writer, which can be shown to be right or wrong by something outside them.'));
out.push(A('**b** **1** **Four sentences, the third of which is _nobody from here gets an answer on that forum and I do not expect that to change_.** ⚠ **Mr Deeb at the registry had kept it for two years and three months and handed it over unopened with the date of handing it over written on the back.**   **2** ⚠ **A verdict on the writer and no information about the writing** — **and a student who reads their own old page as an embarrassment has learnt nothing from a document they spent an evening on.**'));
out.push(NOTE('⚠ **The first four minutes of this unit decide it, and what happens in them is laughter.** **Expect it, do not suppress it, and have the mechanical remedy ready: read the sentence aloud, exactly, with no tone at all.** **Not slowly and not kindly.** **A sentence read without a tone is a sentence somebody wrote** — **and the moment a tone goes on it the student has started commenting instead of reading.** **Demonstrate it once yourself with a sentence of your own if you have one.** ⚠ **The distinction to establish and then rely on for seven cycles is between a claim and a feeling.** **A claim has a date, a named writer and something countable.** **_I was less confident then_ has none of the three** — **and a prediction is the most checkable thing anybody ever writes about themselves, which is why Mr Attar\'s third sentence is worth more than his other three together.**'));
out.push(NOTE('**Three results are possible and the room expects only one.** ⚠ **The claim was wrong** — **the common case, and the one the room is braced for.** **The claim was right** — **three of the ten old documents in this class contained a claim that has held, and all three writers had expected to be embarrassed and were not.** **There was no claim at all** — **two students found no claim anywhere in a page of their own writing, which is the hardest result and the most useful: a page of hopes cannot be checked by anybody, including its writer.** ⚠ **Say all three before Stage 4a.** **A room that has been told only about the first will manufacture a failure, and a manufactured failure is the one thing in this unit that nobody can check.**'));
out.push(S('Language box · Practise'));
out.push(A('**1** **A prediction that was wrong** — _I wrote that nobody from here gets an answer; four answers came since March and the earliest is the nineteenth._   **2** **One that was right** — _I wrote that the inspectorate would not accept a hand-kept book; it has not, in six years._   **3** **An item from a list, checked** — _I wrote that I could not refuse a referee\'s point; point five of the May letter is refused with the office named._   **4** ⚠ **A document with an outcome somebody else supplied** — **the strongest form, because the writer did not produce it.**   **5** ⚠ **One read four times as a writer** — **and asking what in it was a claim takes four minutes and has never been done.**'));
out.push(S('Stage 3 · Practise (sample – Card A)'));
out.push(SAMPLE([
  '**Row 1** _Four answers came between March and November, and the earliest is the nineteenth of March._',
  '**Row 2** ⚠ **Not a claim.** **A difficulty.** **Nothing could settle it, then or now.**',
  '**Row 3** _Section 4.6 of 2 May states nine findings at four degrees._ **A document the writer produced.**',
  '**Row 4** ⚠ **Not a claim.** **A hope.** **The room will want to settle it with _and I am_** — **which is a feeling answering a feeling.**',
  '**Row 5** **A claim, and it has held.** _No branch in this governorate has had a hand-kept book accepted, in six years._ ⚠ **The rarer and more useful result.**',
]));
out.push(S('Stage 3 · Practise (sample – Card B)'));
out.push(SAMPLE([
  '**Row 1** _The desk ran eighty-six words unchanged on 11 June and four times since._',
  '**Row 2** ⚠ **Not a claim.** **_Not good enough yet_ has no measure in it and _yet_ makes it permanently open.**',
  '**Row 3** _Point five of the letter of 12 May is refused, with the office named._',
  '**Row 4** ⚠ **Not a claim.** **A wish, and the comparative makes it unfalsifiable.**',
  '**Row 5** **A claim, and it has held.** _No refusal to the regional director exists in eleven years of the file._ ⚠ **And the writer went looking expecting to find two or three.**',
]));
out.push(S('Stage 3R · Perform – listener task'));
out.push(A('**Rows 2 and 4 on both cards are not claims** — **a difficulty, a hope, a comparative and a wish** — **and nothing can settle any of the four.** ⚠ **Make the room say what would settle each one, and let the silence stand**: that silence is the finding, and it is the reason those four sentences were useless on the day they were written. **Rows 5 are the strongest on either card**: both are predictions about other people, both are checkable, and both have held — **which is the result the room is not expecting and should meet here rather than in their own document.**'));
out.push(S('Stage 4 · Your turn (sample)'));
out.push(SAMPLE([
  '**My oldest document: the covering letter of 21 September last year, sixteen months old.**',
  '**The one sentence in it that is a claim.** _The panel will want the uptake figure and I shall not have it._',
  '**Read flat.** ⚠ **The finding: they wanted it in October and I did not have it, so the claim held** — **and it held because I did nothing about it, which is a worse reason than being wrong.**',
  '**b** ⚠ **My partner said what would settle it was the minute of the October panel, which exists and which I have not read.** **I had assumed I remembered what happened.**',
  '**And the figure from 4a.** **Three sentences in a page of nine, and six of the nine are about how I felt about the application.**',
]));
out.push(S('Stage 4R · Report (sample)'));
out.push(SAMPLE(['Mr Attar\'s envelope was dated the first of December and Mr Deeb at the registry had kept it for two years and three months, and he gave it over unopened with the date of handing it over written on the back. Mrs Tarabishi asked what it said, and four sentences, of which the third is that nobody from here gets an answer on that forum and he did not expect that to change. Mrs Khoury said the room should notice what kind of sentence that is, because it is a prediction with a date on it, made by a named writer, about something that can be counted, and that is evidence and not a feeling. Dr Qabbani said and it was wrong, and it was wrong and he can date when: four answers since March, the earliest the nineteenth, and he had stopped expecting them to matter by about May, which is a second change and a different one. Mrs Oueidat said the first reaction in the room was laughter, and Mrs Khoury said it always is and it is the thing to get past in the first four minutes, because embarrassment produces a verdict on the writer and no information about the writing. Mr Tayara asked how you stop it, and Mrs Oueidat said read the sentence aloud, exactly, with no tone at all, because a sentence read without a tone is a sentence somebody wrote. Mrs Rizk said hers is not a letter but her September list, and it is the same object and sixteen months old, and the list has the better property: it is a set of dated claims about what its writer could not do. Mrs Ajouz mentioned her first letter to the officer, and Mr Attar said it was returned in eleven days so it has a date and an outcome, and an outcome is worth more than any number of claims because somebody else supplied it. Mr Zahreddine said his is three years old and he has read it four times, and then he has read it four times as a writer and not once as evidence. Mr Shihabi asked what happens if the old sentence turns out to be right, and then say so, and three of the ten old documents contained a claim that has held. And Mr Attar said the thing he will take away is the back of the envelope: Mr Deeb wrote the date he handed it over, which nobody asked him to do, and the two dates together are the only thing in this that nobody could have arranged afterwards.']));
out.push(A('⚠ **The last line is the one to carry out of the cycle: Mr Deeb wrote the date he handed it over, and nobody asked him to.** **Say it and then say what it is doing**: two dates in two hands are the only part of the whole exercise that cannot have been arranged afterwards, **and the keeper supplied one of the two.** **15.5 corrects the reason Mr Attar gives for it and the finding survives** — **so do not settle the point here, and do not let the room settle it either.**'));
out.push(S('Board clinic – typical mistakes'));
out.push(A('**1** ⚠ _I cannot believe I wrote that._ → **a verdict on the writer; no information about the writing.**   **2** **A tone on the old sentence** → **commenting, not reading.**   **3** ⚠ **A feeling treated as a claim** → **nothing can settle it, and the silence is the finding.**   **4** **A manufactured failure** → **the room has been told only about the common result.**   **5** ⚠ **_I was less confident then_** → **a comparison with no evidence on either side.**   **6** **Reading the old document again instead of interrogating it** → **four readings as a writer and none as evidence.**'));
out.push(S('Board – the ten old documents'));
out.push(A('⚠ **Build this with the room at Stage 1a and fill the last two columns at Stage 4.** **The right-hand column is the finding of the cycle and it is a count**: in this class the claims-per-page ran from none to four, and the two pages with none were pages of hopes.'));
out.push(table(['THE DOCUMENT', 'AGE', 'CLAIMS ON THE PAGE', 'RESULT'], [
  ['**A sealed letter, four sentences**', '**2 yr 3 mo**', '**One of four**', '⚠ **Wrong, and dated: 19 March.**'],
  ['**A sealed letter, unopened**', '**2 yr 3 mo**', '**Not known**', '**15.3 — three guesses instead.**'],
  ['**A _cannot yet_ list, nine items**', '**16 mo**', '**Nine of nine**', '**Four gone, two absences, three held.**'],
  ['**A covering letter to an officer**', '**15 mo**', '**Three of nine**', '⚠ **Outcome supplied by the officer.**'],
  ['**An opinion on an east elevation**', '**3 yr**', '**Four**', '**Read four times as a writer, never as evidence.**'],
  ['**A first referee reply**', '**20 mo**', '**Two**', '**One held, one wrong.**'],
  ['**A court summary**', '**19 mo**', '**One**', '**Held.**'],
  ['**A timetable submission**', '**16 mo**', '**None**', '⚠ **A page of hopes. The hardest result.**'],
  ['**A release note**', '**22 mo**', '**Two**', '**Both wrong, neither datable.**'],
  ['**A grant application**', '**2 yr**', '**None**', '⚠ **A page of hopes.**'],
], [2.4, 0.9, 1.4, 2.6]));
out.push(S('Stage 5 · Read'));
out.push(A('**1** ⚠ **The third: _nobody from here gets an answer on that forum and I do not expect that to change._** **Four answers since March, the earliest the nineteenth, and he has the thread** — **so the prediction failed and he can date the failure, which he calls the most useful thing in the whole envelope.**'));
out.push(A('**2** ⚠ **He does write English — about nine hundred words a week — and almost none of it is for people who do not know him**, which was the thing the second sentence wanted. **It was unexpected because the first sentence stopped being true in a direction he had not predicted**, and no amount of rereading the letter would have shown that.'));
out.push(A('**3** ⚠ **The fourth: _if this is still true in two years I shall stop asking._** **A condition, with a date and a consequence, and the only thing in the letter that would have told him what to do if the prediction had held.** **On hedging he says he would now hedge two of the four and is not sure he should** — **_I do not expect that to change_ was checkable because it was plain, and _it seems unlikely to change in the short term_ could not have been wrong.**'));
out.push(S('Stage 6 · Write with help (sample)'));
out.push(SAMPLE([
  '**M. TAYARA** · _note on the submission of 21 September_ · _nine sentences, no claims_ · **4 December**',
  '**The submission was written on 21 September last year and the directorate returned it on 9 October.** ⚠ **I have kept both.**',
  '**The nine sentences, in the order I wrote them.** **One: _the school respectfully requests consideration of the afternoon timetable._** **Two: _we believe the present arrangement is not in the interests of the pupils._** **Three: _we hope the directorate will look favourably on this request._**',
  '**None of the nine is evidence, and that is the finding.** **Not one has a figure, a date or a countable thing in it** — **and the four hundred and ten pupils are not mentioned anywhere.**',
]));
out.push(S('Stage 7 · Write freely (sample, 282 words)'));
out.push(SAMPLE([
  '**M. TAYARA** · _note on the submission of 21 September_ · _nine sentences, no claims_ · **5 December**',
  '**The submission was written on 21 September last year and the directorate returned it on 9 October with three words on the slip.** ⚠ **I have kept both documents and had not put them side by side until this week.**',
  '**The nine sentences, in the order I wrote them.** **One: _the school respectfully requests consideration of the afternoon timetable._** **Two: _we believe the present arrangement is not in the interests of the pupils._** **Three: _we hope the directorate will look favourably on this request._** **The remaining six are of the same kind and I am not going to quote them all.**',
  '**None of the nine is evidence and that is the finding of this note.** ⚠ **Not one has a figure, a date or a countable thing in it.** **Four hundred and ten pupils and two afternoon rooms are the whole of my case and neither number appears anywhere in the page** — **and I had believed for fourteen months that the submission was refused because the directorate does not amend timetables.**',
  '**What the slip says, which I had read and not read.** _On what grounds._ **Three words, and they are a question** — **and a question is a thing that can be answered, which a refusal is not.** **I had filed it as a refusal.**',
  '**What I would now call the claim in the document, and it is not in the document.** **It was in my head: that the directorate would refuse any request from this school.** ⚠ **Two requests from 2017 are in the file, both refused in one line, and neither is mine** — **so the claim I was acting on was about two letters written by somebody else before I arrived.**',
  '**And the thing that is not about this submission.** **A page with no countable thing in it cannot be refused on its merits, because it has not offered any** — **and it cannot be defended either, which is why fourteen months produced nothing.**',
]));
out.push(S('Stage 7P · Respond (sample slip — band 3, with the answer)'));
out.push(SAMPLE([
  '**THE SLIP, unsigned.** **Reader: the directorate officer who wrote the three words.** **Absent: whether the school has since submitted anything with a figure in it.** **Criterion — the line copied:** _"Four hundred and ten pupils and two afternoon rooms are the whole of my case and neither number appears anywhere in the page"_. ⚠ **The note establishes the fault and does not say whether it has been repaired** — **and that officer has been waiting fourteen months for an answer to a question.**',
  '**THE WRITER\'S ONE LINE.** ⚠ _Conceded: the submission of 4 January carries both figures and the arithmetic at annexe A, and the note now says so in the last paragraph._',
  '**A second slip, unsigned.** **Reader: the writer himself.** **Absent: any account of why he read a question as a refusal.**',
  '**THE WRITER\'S ONE LINE.** ⚠ _Refused: the note records that he did, which is the evidence, and an explanation of it would be a sentence about my state of mind in October of last year, which nothing can check._',
]));
out.push(S('Stage 7R · Share'));
out.push(A('⚠ **One student reads their oldest sentence twice: once as they feel about it and once flat.** **The room says which version it could hear the words of, and it will be surprised by how much it had not heard the first time.** **Then one number on the board: claims per page.** **In this class the counts ran from none to four** — **and the two pages with none are the finding of the cycle, not its failures.** **Then Mr Attar\'s sentence, and leave 15.5 to correct the reason.**'));

// ===================== 15.2 =====================
out.push(pb());
out.push(h2('15.2  What I wrote, and what I no longer believe'));
out.push(S('Stage 1 · Get ready'));
out.push(A('**a** Open. ⚠ **The old sentence and then a stop**, and leave the second column empty on the board. **Six of ten first answers give the old sentence and a feeling about it** — **and the empty column is where the cycle lives, so do not fill it in for anybody.**'));
out.push(A('**b** Complete: **1** and **3**. ⚠ **Both have all three parts and a _because_ that is a fact.** **2, 4 and 5 have the first part and nothing else** — _some things I would not write now_, _I was wrong about quite a lot_, _I think differently now_ — **and the room should be made to say what is missing, which is the same thing in all three cases: anything a reader could check.**'));
out.push(S('Stage 2 · Listen and read'));
out.push(A('**a** **B** — ⚠ **three parts**: what you wrote, what you no longer believe, and a _because_ that is a fact and not a reason.'));
out.push(A('**b** **1** ⚠ **A fact and not a reason.** **_Because four answers came between March and November_ is a fact; _because I have more confidence now_ is a reason, and a reason is something you supply about yourself.**   **2** ⚠ **The honest sentence says so**: _I wrote it, I still believe it, and nothing since has tested it_ — **which is the entry three people in this room have and nobody expected to be allowed.**'));
out.push(NOTE('⚠ **The invented change is the one fault in this unit that no check can find afterwards, so the prevention has to happen at Stage 4b.** **The shape of the exercise invites a change of mind at every line.** **A student who has not changed their mind will invent a change rather than write the third sentence** — **and the test question is one sentence: _would you have written this if you had not changed your mind?_** **If the answer is yes, the change is invented.** **Two students in this class found that out at 4b and both rewrote the entry as _I still believe it_.** ⚠ **Say before Stage 4 that the still-believed entry is a legitimate result and that three people in the room will have one.** **A room that believes the cycle requires a conversion will produce ten of them.**'));
out.push(NOTE('**Three forms of _because_, and the third has to be taught because nobody arrives with it.** ⚠ **One: what happened** — _four answers came_ — **for a sentence about the world.** **Two: a document you have written since** — _point five of the May letter is a refusal with the office named_ — **for a sentence about yourself, which is 12.1 and the room will not recognise it here.** **Three: an absence with a denominator** — _nobody has asked since June, for the first time in four submissions_. ⚠ **The third is the strongest and the least reached for.** **Mrs Tarabishi\'s list is nine sentences about herself and not one about the world**, which means the whole list was always going to be settled by her own documents — **a narrower test than she thought she was setting, and worth saying to a room whose lists are the same shape.**'));
out.push(S('Language box · Practise'));
out.push(A('**1** **About the world** — _I wrote that nobody from here gets an answer, and I no longer believe it, because four came between March and November._   **2** **About yourself, with a document** — _…because section 4.6 of 2 May states nine findings at four degrees._   **3** **About yourself, with an absence** — _…because nobody has asked since June, for the first time in four submissions._   **4** ⚠ **One you still believe** — _I wrote it, I still believe it, and the last three notes ran to 380, 392 and 381._   **5** ⚠ **One that changed and changed back** — **two dates on one belief, which is the most honest entry available.**'));
out.push(S('Stage 3 · Practise (sample – Card A)'));
out.push(SAMPLE([
  '**Row 1** _I wrote that nobody from here gets an answer, and I no longer believe it, because four came between March and November._',
  '**Row 2** ⚠ **Still believed.** _I wrote it, I still believe it, and no branch in this governorate has had one accepted in six years._',
  '**Row 3** _…and I no longer believe it, because section 4.6 of 2 May states nine findings at four degrees._ **A document.**',
  '**Row 4** ⚠ **Still believed.** _…and the last three ran to 380, 392 and 381 against a figure of 300._ **The figures are the point: a note eighty words over instead of a hundred is the same note.**',
  '**Row 5** _…because the desk ran eighty-six words unchanged on 11 June and four times since._ ⚠ **Somebody else supplied it.**',
]));
out.push(S('Stage 3 · Practise (sample – Card B)'));
out.push(SAMPLE([
  '**Row 1** _…and I no longer believe it, because point five of the letter of 12 May is refused with the office named._',
  '**Row 2** ⚠ **Still believed.** _…and there is no refusal to the regional director in eleven years of the file._',
  '**Row 3** _…because I did it on 10 May in eleven minutes and removed two sentences._',
  '**Row 4** ⚠ **Still believed.** _…and six calques have been found by other people and none by me._ **The denominator is six to nothing.**',
  '**Row 5** _…because the desk has not changed a first paragraph of mine since 11 June._ ⚠ **An absence, and the date is the desk\'s.**',
]));
out.push(S('Stage 3R · Perform – listener task'));
out.push(A('**Rows 2 and 4 on both cards are still believed and the form does not change.** ⚠ **Make the room notice that the still-believed entries are the ones with figures in them** — **six years, eleven years, 380 and 392, six to nothing** — **because a belief that has survived needs more evidence than one that has gone, and the room expects the opposite.** **Rows 5 on both cards are settled by an absence or by somebody else\'s act**, and the listener should name which of the three forms was used in every row.'));
out.push(S('Stage 4 · Your turn (sample)'));
out.push(SAMPLE([
  '**My old sentence: _I shall never get the uptake figure out of the regional office._**',
  '**First version.** _…and I no longer believe it, because I am more willing to ask now._ ⚠ **A reason, and my partner wrote it down and I had not noticed.**',
  '**Repaired.** _…and I no longer believe it, because the return arrived on 3 February, two days after I asked for it._',
  '**b** ⚠ **The test question: would I have written this if I had not changed my mind?** **No** — **the return is a fact and I would have had to report it either way.**',
  '**And the entry I rewrote.** **One of my four became _I still believe it_**: the governorate has still allocated no register, and nothing I have done has tested it.',
]));
out.push(S('Stage 4R · Report (sample)'));
out.push(SAMPLE(['Mrs Khoury said the third part is the because and it has to be a fact and not a reason: because four answers came between March and November is a fact, and because I have more confidence now is a reason, and a reason is a thing you supply about yourself. Mr Attar asked what happens if there is no fact, and then you still believe it and the honest sentence says so: I wrote it, I still believe it, and nothing since has tested it, which is the entry three people in the room have and nobody expected to be allowed. Mrs Oueidat said that is the harder half of the cycle, because the whole shape of the exercise invites a change of mind, and a student who has not changed their mind will invent a change rather than write the third sentence, and an invented change is the only thing in this unit that cannot be checked by anybody. Mrs Tarabishi said her old sentence was about herself and not the world, and Mrs Khoury said those are the two kinds and they need different facts: a sentence about the world is settled by what happened, and a sentence about yourself by a document you have written since. Dr Qabbani said his is about himself and he cannot find the document, and then look for the absence instead, which is the third form: nobody has asked me about my search since June, for the first time in four submissions, a negative with a denominator. Mr Tayara asked about the weight of the two halves, and equal, with the reason unstressed, because a student who leans on no longer has announced a conversion and a conversion is a thing the room congratulates. Mrs Ajouz said hers changed and then changed back, and then write both dates and the sentence is better for it. Mr Zahreddine asked whether it is ever three sentences, and one sentence, because three sentences let you explain and explaining is what the room does instead of fixing a date. Mr Shihabi asked about the ones that were right, and they get the same form with the middle clause reversed, and nothing in the cycle requires anybody to have been wrong. And Mrs Tarabishi said the thing she will take away is the two kinds: her list was nine sentences about herself and not one about the world, so every one of them needs a document she has written since. Mrs Khoury said that is a finding about the list and not about the year, because a list of nine sentences about yourself has set a narrower test than its writer intended. And Mrs Ajouz said the thing she will take away is the still-believed group, because she had assumed the exercise required her to have changed her mind about everything.']));
out.push(A('⚠ **The last line is the one to carry out of the cycle: her list was nine sentences about herself and not one about the world.** **Put it to the room as a question before reading the report**: how many of your own list items are about the world? **In this class the answer was none, for all ten students** — **and it means every _cannot yet_ list in the room set a test that only the writer\'s own documents can settle.**'));
out.push(S('Board clinic – typical mistakes'));
out.push(A('**1** ⚠ _…because I have more confidence now._ → **a reason, not a fact.**   **2** **An invented change** → **the test question at 4b finds it and nothing afterwards does.**   **3** ⚠ **Three sentences instead of one** → **the room explains instead of fixing a date.**   **4** **An absence with no denominator** → **a hope.**   **5** ⚠ **Leaning on _no longer_** → **a conversion announced, and the room congratulates it.**   **6** **No still-believed entry anywhere** → **three people in the room have one and the room thinks it is not allowed.**'));
out.push(S('Stage 5 · Read'));
out.push(A('**1** ⚠ **Every one of the nine is about her and not one is about the world.** **It follows that the whole list was always going to be settled by documents she wrote herself** — **which is a narrower test than she thought she was setting, and she had not noticed it in sixteen months of marking the list.**'));
out.push(A('**2** ⚠ **That referees would always ask about her search — nobody has since June, for the first time in four submissions; and that the desk would always query her covering notes — none of the last four has been queried.** **Neither is a thing she did.** **An absence needs a denominator or it is a hope.**'));
out.push(A('**3** ⚠ **She nearly wrote that the third group had improved.** **It has not**: the figures are 380, 392 and 381 against a figure of 300, **and a note eighty words over instead of a hundred is not an improvement, it is the same note.** **The sheet invites a change of mind at every line and that is the thing to resist.**'));
out.push(S('Stage 6 · Write with help (sample)'));
